const geminiItems = $input.all();
const initialEngineItems = $('Lead Qualification Matrix').all();

return geminiItems.map((item, index) => {
  // Grab the data outputted from your previous code node safely
  const prevData = initialEngineItems[index]?.json || {};
  const firstName = prevData.firstName || '';
  const lastName = prevData.lastName || '';
  const email = prevData.email || '';
  const phone = prevData.phone || '';
  const company = prevData.company || '';
  const budgetStr = prevData.budget || '';
  const numericBudget = prevData.numericBudget || 0;
  const notesText = prevData.notes || '';
  const hasUrgentKeyword = prevData.urgency_detected === 'YES';

  // Start with the score calculated in the previous node
  let clampedScore = prevData.final_score || 0;

  // Extract and Parse AI Intent directly from the new AI Agent output schema
  const intent = item.json.intent || 'Exploring';
  const summary = item.json.summary || item.json.output || '';

  // Apply AI Intent Bonus if Immediate Buying is detected
  if (intent === 'Immediate Buying' && clampedScore < 100) {
    clampedScore = Math.min(100, clampedScore + 10);
  }

  return {
    json: {
      firstName: firstName,
      lastName: lastName,
      email: email,
      phone: phone,
      company: company,
      budget: budgetStr,
      numericBudget: numericBudget,
      notes: notesText,
      final_score: clampedScore,
      lead_tier: clampedScore >= 70 ? 'HOT' : 'WARM/COLD',
      urgency_detected: hasUrgentKeyword ? 'YES' : 'NO',
      ai_intent: intent,
      ai_summary: summary
    }
  };
});

