const sanitizerItems = $("Data Cleansing, & E.164 Formatter").all();

return $input.all().map((item, index) => {
  const cleanData = sanitizerItems[index]?.json?.sanitized || sanitizerItems[index]?.json || {};

  const firstName = cleanData.firstName || '';
  const lastName = cleanData.lastName || '';
  const email = cleanData.email || '';
  const phone = cleanData.phone || '';
  const company = cleanData.company || '';
  const budgetStr = String(cleanData.budget || '');
  const notesText = cleanData.notes || '';
  const notes = notesText.toLowerCase();

  const numericBudget = cleanData.numericBudget || parseFloat(budgetStr.replace(/[^0-9.]/g, '')) || 0;

  let score = 0;

  // Scoring Logic
  if (numericBudget >= 20000) score += 70;
  else if (numericBudget >= 5000) score += 30;
  else if (numericBudget > 0) score += 10;

  if (company.length > 0 && company !== 'empty') score += 20;

  const urgentKeywords = ['asap', 'bleeding', 'urgent', 'immediately', '14 days', 'now'];
  const hasUrgentKeyword = urgentKeywords.some(kw => notes.includes(kw));
  if (hasUrgentKeyword) score += 20;

  // Clamp Score & Apply Micro-Budget Guardrail (< $500 max cap at 45)
  let finalScore = Math.min(Math.max(score, 0), 100);
  if (numericBudget > 0 && numericBudget < 500) {
    finalScore = Math.min(finalScore, 45); 
  }

  // Clean Output Columns (including notes)
  return {
    json: {
      firstName,
      lastName,
      email,
      phone,
      company,
      budget: budgetStr,
      numericBudget,
      notes: notesText,
      final_score: finalScore,
      lead_tier: finalScore >= 70 ? 'HOT' : 'WARM/COLD',
      urgency_detected: hasUrgentKeyword ? 'YES' : 'NO'
    }
  };
});

// ============================================================================
// HELPER FUNCTIONS (Declared before main execution loop)
// ============================================================================

// 1. Global E.164 Phone Formatter
function formatToE164(rawPhone) {
  if (!rawPhone || typeof rawPhone !== 'string') return '';

  // Remove unwanted letters or characters (e.g., '+44 (ss0)' -> '+44 0')
  const cleanStr = rawPhone.replace(/[a-zA-Z]/g, '');

  // Extract all digits
  const digits = cleanStr.replace(/\D/g, '');
  if (!digits) return '';

  // If string started with '+', preserve international format
  if (rawPhone.trim().startsWith('+')) {
    return `+${digits}`;
  }

  return digits;
}

// 2. Range & Multiplier Budget Parser
function parseBudgetToNumber(rawStr) {
  if (!rawStr || typeof rawStr !== 'string') return 0;

  const str = rawStr.toLowerCase().trim();

  // Check for 'k' (thousands) or 'm' (millions)
  const isK = str.includes('k');
  const isM = str.includes('m');
  const multiplier = isM ? 1000000 : (isK ? 1000 : 1);

  // Extract digits and decimals
  const numbers = str.match(/\d+(\.\d+)?/g);
  if (!numbers || numbers.length === 0) return 0;

  // Convert numbers with multiplier applied
  const parsedValues = numbers.map(num => parseFloat(num) * multiplier);

  // Return maximum value found in range
  return Math.max(...parsedValues);
}

// 3. Title Case Capitalization Helper
function capitalize(str) {
  if (!str) return '';
  return str
    .trim()
    .toLowerCase()
    .replace(/(?:^|\s|-)\S/g, char => char.toUpperCase());
}

// 4. Notes Sanitizer
function sanitizeNotes(notesStr) {
  if (!notesStr || typeof notesStr !== 'string') return '';
  return notesStr.replace(/[\r\n]+/g, ' ').trim();
}


// ============================================================================
// MAIN EXECUTION LOOP
// ============================================================================
return $input.all().map(item => {
  // Safely extract payload
  const payload = item?.json?.body ?? item?.json ?? {};

  // 1. Sanitize & Normalize Email (Fixes accidental ';' or ',' typos from international inputs)
  const rawEmail = payload?.email ?? '';
  const cleanEmail = rawEmail
    .replace(/;/g, '.')
    .replace(/,/g, '.')
    .replace(/\s+/g, '')
    .toLowerCase()
    .trim();

  // 2. Parse & Title-Case Names ("johnny jay" -> "Johnny Jay")
  const firstName = capitalize(payload?.firstName ?? '');
  const lastName = capitalize(payload?.lastName ?? '');
  const fullName = [firstName, lastName].filter(Boolean).join(' ');

  // 3. Normalize Company (Default to "empty" if missing)
  const rawCompany = capitalize(payload?.company ?? '').replace(/\s+/g, ' ');
  const company = rawCompany || 'empty';

  // 4. Budget Processing
  const rawBudget = (payload?.budget ?? '').trim();
  const numericBudget = parseBudgetToNumber(rawBudget);

  // 5. Notes Processing
  const rawNotes = payload?.notes ?? '';
  const cleanNotes = sanitizeNotes(rawNotes);

  // 6. E.164 Phone Formatting
  const sanitizedPhone = formatToE164(payload?.phone ?? '');

  // Return clean output object
  return {
    json: {
      ...item.json,
      firstName,
      lastName,
      fullName,
      email: cleanEmail,
      phone: sanitizedPhone,
      company,
      budget: rawBudget,
      numericBudget,
      notes: cleanNotes,
      isSpamDomain: item.json?.isSpamDomain ?? false
    }
  };
});

